  1318          return(NULL);
  1319
  1320      buffer = xmlBufferCreate();
  1321      if (buffer == NULL)
  1322         return NULL;
  1323
  1324      for ( ; node != NULL; node = node->next) {
  1325         switch (node->type) {
  1326         case XML_TEXT_NODE:
  1327         case XML_CDATA_SECTION_NODE:
  1328             xmlBufferCat(buffer, node->content);
  1329             break;
